import{_ as e,o as t,c as n,a2 as a}from"./chunks/framework.DGu13UIe.js";const o="/bagent/lessons/30-vscode-extension/image.png",b=JSON.parse('{"title":"第 30 课 · VS Code 侧边栏插件","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/30-vscode-extension/doc.md"},"headers":[],"relativePath":"chapters/30-vscode-extension.md","filePath":"chapters/30-vscode-extension.md"}'),i={name:"chapters/30-vscode-extension.md"};function l(r,s,p,d,c,h){return t(),n("div",null,[...s[0]||(s[0]=[a('<h1 id="第-30-课-·-vs-code-侧边栏插件" tabindex="-1">第 30 课 · VS Code 侧边栏插件 <a class="header-anchor" href="#第-30-课-·-vs-code-侧边栏插件" aria-label="Permalink to &quot;第 30 课 · VS Code 侧边栏插件&quot;">​</a></h1><p><strong>约 45 分钟</strong> · <a href="/bagent/chapters/29-agent-split.html">第 29 课</a> 之后</p><p>没写过 VS Code 插件？可先读 <a href="/bagent/chapters/101-vscode-extension.html">第 101 课</a>（流程概览），需要完整小例子时看 <a href="/bagent/chapters/102-vscode-calculator.html">第 102 课</a>，再回来跟做本课。</p><p>订阅 <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 的 Agent 事件，在 <strong>左侧活动栏</strong> 打开聊天侧边栏：输入框 + 气泡流式回复，不用命令面板、不用输出面板。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ch28 server  ──SSE──►  侧边栏 Webview（本课）</span></span></code></pre></div><hr><h2 id="_1-用起来什么样" tabindex="-1">1. 用起来什么样 <a class="header-anchor" href="#_1-用起来什么样" aria-label="Permalink to &quot;1. 用起来什么样&quot;">​</a></h2><ol><li>活动栏多了一个 <strong>对话图标</strong>（bagent）</li><li>点开侧边栏：<strong>上面聊天记录，下面输入框</strong></li><li>发送后 <code>ChunkUpdated</code> 逐字追加到 AI 气泡，<code>ToolCallStart</code> 显示黄条工具行</li></ol><p>内核仍是 <code>subscribe.ts</code> 解析 <code>AgentEvent</code>；只是 <strong>渲染从 Output Channel 换成 Webview HTML</strong>。</p><p>F5 跑通后大致是这样（<strong>Extension Development Host</strong> 新窗口，左侧 <strong>BAGENT: AGENT</strong>）：</p><p><img src="'+o+`" alt="VS Code 侧边栏聊天气泡"></p><ul><li>标题栏 <strong><code>[Extension Development Host]</code></strong> = 插件调试窗口</li><li>活动栏 <strong>对话图标</strong> → 侧边栏输入框 + 蓝/灰气泡</li><li>顶部灰字 <code>需先 npm run ch28:server</code> 提醒先起发布端</li><li>流式正文、<code>[工具] read_file(...)</code> 与第 28 课终端 client 同源，只是画在 Webview 里</li></ul><hr><h2 id="_2-目录" tabindex="-1">2. 目录 <a class="header-anchor" href="#_2-目录" aria-label="Permalink to &quot;2. 目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lessons/30-vscode-extension/</span></span>
<span class="line"><span>  src/extension.ts      # 注册 WebviewViewProvider</span></span>
<span class="line"><span>  src/sidebar.ts        # 侧边栏 HTML + 与 extension 通信</span></span>
<span class="line"><span>  src/subscribe.ts      # SSE 订阅（同 ch28 client）</span></span>
<span class="line"><span>  src/events.ts</span></span>
<span class="line"><span>  package.json          # viewsContainers + views</span></span></code></pre></div><hr><h2 id="_3-动手-零基础版" tabindex="-1">3. 动手（零基础版） <a class="header-anchor" href="#_3-动手-零基础版" aria-label="Permalink to &quot;3. 动手（零基础版）&quot;">​</a></h2><p>没写过 VS Code 插件也照做即可。全程会涉及 <strong>两个窗口、两个终端</strong>，第一次容易晕，下面按顺序来。</p><h3 id="_3-0-先搞清-两个窗口各是什么" tabindex="-1">3.0 先搞清：两个窗口各是什么 <a class="header-anchor" href="#_3-0-先搞清-两个窗口各是什么" aria-label="Permalink to &quot;3.0 先搞清：两个窗口各是什么&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────┐     F5      ┌──────────────────────────────────┐</span></span>
<span class="line"><span>│ 窗口 A：写插件代码的窗口       │  ───────►  │ 窗口 B：Extension Development Host │</span></span>
<span class="line"><span>│ 打开 lessons/30-vscode-…    │            │ 标题带 [Extension Development Host] │</span></span>
<span class="line"><span>│ 在这里按 F5，看调试日志       │            │ 在这里用侧边栏聊天 ← 你要试的是这个 │</span></span>
<span class="line"><span>└─────────────────────────────┘            └──────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>窗口 A</strong>：开发者用的，资源管理器里是 <code>src/extension.ts</code>、<code>package.json</code>。</li><li><strong>窗口 B</strong>：F5 后 <strong>自动弹出的新窗口</strong>，你的插件只装在这里。</li><li>常见失误：在 <strong>窗口 A</strong> 里找侧边栏图标——那里 <strong>没有</strong>，要去 <strong>窗口 B</strong>。</li></ul><p>另有一个 <strong>终端</strong> 跑 <code>ch28:server</code>（Agent 大脑），和 A、B 都无关，但要一直开着。</p><hr><h3 id="_3-1-终端-起-agent-服务-在-bagent-仓库根目录" tabindex="-1">3.1 终端：起 Agent 服务（在 bagent 仓库根目录） <a class="header-anchor" href="#_3-1-终端-起-agent-服务-在-bagent-仓库根目录" aria-label="Permalink to &quot;3.1 终端：起 Agent 服务（在 bagent 仓库根目录）&quot;">​</a></h3><p>打开系统终端（或 Cursor 里开一个 Terminal 标签），<code>cd</code> 到 <strong>bagent 根目录</strong>（能看到 <code>package.json</code>、<code>lessons/</code> 的那一层）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /你的路径/bagent</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch28:server</span></span></code></pre></div><p>看到类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 发布端 http://localhost:3028</span></span>
<span class="line"><span>POST /chat  body: { &quot;message&quot;: &quot;...&quot; }  →  text/event-stream</span></span></code></pre></div><p><strong>这个终端不要关</strong>，最小化即可。没有它，侧边栏发消息会连不上。</p><hr><h3 id="_3-2-编译插件-仍在-bagent-根目录" tabindex="-1">3.2 编译插件（仍在 bagent 根目录） <a class="header-anchor" href="#_3-2-编译插件-仍在-bagent-根目录" aria-label="Permalink to &quot;3.2 编译插件（仍在 bagent 根目录）&quot;">​</a></h3><p><strong>再开一个终端</strong>（或关掉 server 会断，请用新标签），执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /你的路径/bagent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch30:compile</span></span></code></pre></div><p>成功会生成 <code>lessons/30-vscode-extension/out/extension.js</code>。<br><strong>每次改了 <code>src/</code> 里的代码</strong>，都要重新跑这一条，再在窗口 B 里重载（见 3.6）。</p><hr><h3 id="_3-3-窗口-a-只打开插件文件夹-重要" tabindex="-1">3.3 窗口 A：只打开插件文件夹（重要） <a class="header-anchor" href="#_3-3-窗口-a-只打开插件文件夹-重要" aria-label="Permalink to &quot;3.3 窗口 A：只打开插件文件夹（重要）&quot;">​</a></h3><ol><li>打开 <strong>VS Code 或 Cursor</strong>（若已开着 bagent 整个大仓库，先 <strong>文件 → 关闭文件夹</strong>）。</li><li><strong>文件 → 打开文件夹…</strong>（macOS 也可 <strong>文件 → Open Folder…</strong>）。</li><li>选中 <strong><code>bagent/lessons/30-vscode-extension</code></strong> 这一层，点打开。</li></ol><p><strong>不要</strong> 打开整个 <code>bagent</code> 根目录——根目录没有本课的 <code>.vscode/launch.json</code>，按 F5 会懵。</p><p>打开对了的话，左侧资源管理器顶层应是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>30-VSCODE-EXTENSION</span></span>
<span class="line"><span>  .vscode</span></span>
<span class="line"><span>  src</span></span>
<span class="line"><span>  out</span></span>
<span class="line"><span>  package.json</span></span>
<span class="line"><span>  …</span></span></code></pre></div><hr><h3 id="_3-4-按-f5-弹出窗口-b" tabindex="-1">3.4 按 F5，弹出窗口 B <a class="header-anchor" href="#_3-4-按-f5-弹出窗口-b" aria-label="Permalink to &quot;3.4 按 F5，弹出窗口 B&quot;">​</a></h3><ol><li>在 <strong>窗口 A</strong> 按键盘 <strong>F5</strong>（或菜单 <strong>运行 → 启动调试</strong>；左侧「运行和调试」虫子图标 → 选 <strong>「运行第 30 课插件」</strong> → 绿三角）。</li><li>等待几秒，会 <strong>再弹出一个新的编辑器窗口</strong>。</li><li>看新窗口标题，通常带有 <strong><code>[Extension Development Host]</code></strong> —— 这就是 <strong>窗口 B</strong>。</li></ol><p>窗口 A 底部「调试控制台」里若出现 <code>punycode</code>、<code>Claude code extension is now deactivated</code> 等，多半是 Cursor/别的扩展的日志，<strong>可忽略</strong>，以窗口 B 能不能聊天为准。</p><hr><h3 id="_3-5-窗口-b-打开侧边栏并聊天" tabindex="-1">3.5 窗口 B：打开侧边栏并聊天 <a class="header-anchor" href="#_3-5-窗口-b-打开侧边栏并聊天" aria-label="Permalink to &quot;3.5 窗口 B：打开侧边栏并聊天&quot;">​</a></h3><p>在 <strong>窗口 B</strong>（不是 A）：</p><ol><li>看 <strong>最左侧竖条</strong>（活动栏），点 <strong>对话气泡图标</strong>（鼠标悬停可能显示 bagent）。</li><li>左侧出现面板，标题类似 <strong>BAGENT: AGENT</strong>，顶部有灰字 <code>需先 npm run ch28:server</code>。</li><li>底部输入框打字，点 <strong>发送</strong>。</li><li>应出现蓝色「你」气泡、灰色 AI 气泡流式增长；调工具时有 <code>[工具] read_file(...)</code>。</li></ol><p>找不到图标时：<code>Cmd+Shift+P</code>（Mac）或 <code>Ctrl+Shift+P</code>（Windows）→ 输入 <strong><code>bagent: 打开侧边栏</code></strong> → 回车。</p><p>效果见上文截图。</p><hr><h3 id="_3-6-改代码后怎么刷新" tabindex="-1">3.6 改代码后怎么刷新 <a class="header-anchor" href="#_3-6-改代码后怎么刷新" aria-label="Permalink to &quot;3.6 改代码后怎么刷新&quot;">​</a></h3><ol><li>窗口 A 里改 <code>src/*.ts</code></li><li>终端再 <code>npm run ch30:compile</code></li><li>到 <strong>窗口 B</strong> 按 <strong>Cmd+R</strong>（Mac）或 <strong>Ctrl+R</strong>（Win）重载扩展开发宿主</li><li>或关掉窗口 B，回窗口 A 再按一次 F5</li></ol><hr><h3 id="_3-7-一条龙检查清单" tabindex="-1">3.7 一条龙检查清单 <a class="header-anchor" href="#_3-7-一条龙检查清单" aria-label="Permalink to &quot;3.7 一条龙检查清单&quot;">​</a></h3><ul><li>[ ] 终端里 <code>ch28:server</code> 在跑</li><li>[ ] <code>npm run ch30:compile</code> 无报错</li><li>[ ] 窗口 A 打开的是 <strong><code>lessons/30-vscode-extension</code></strong>，不是整个 bagent</li><li>[ ] 按 F5 后出现了 <strong>带 [Extension Development Host] 的窗口 B</strong></li><li>[ ] 在 <strong>窗口 B</strong> 左侧点了对话图标并发送成功</li></ul><hr><h2 id="_4-侧边栏怎么和插件主进程说话" tabindex="-1">4. 侧边栏怎么和插件主进程说话 <a class="header-anchor" href="#_4-侧边栏怎么和插件主进程说话" aria-label="Permalink to &quot;4. 侧边栏怎么和插件主进程说话&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Webview（HTML）  --postMessage({type:&#39;ask&#39;})--&gt;  extension.ts</span></span>
<span class="line"><span>extension.ts     --subscribeChat SSE--&gt;           ch28 server</span></span>
<span class="line"><span>extension.ts     --postMessage({type:&#39;event&#39;})--&gt; Webview 更新气泡</span></span></code></pre></div><p>和 <a href="/bagent/chapters/26-agent-events.html">第 26 课</a> 一样：<strong>事件在 extension 里收到，UI 只负责画</strong>；这里 UI 是 Webview 里的 JS，不是 <code>terminal.ts</code>。</p><hr><h2 id="_5-常见问题" tabindex="-1">5. 常见问题 <a class="header-anchor" href="#_5-常见问题" aria-label="Permalink to &quot;5. 常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>按 F5 没反应 / 找不到配置</td><td>是否打开了 <strong><code>30-vscode-extension</code> 文件夹</strong>（见 3.3）</td></tr><tr><td>看不到对话图标</td><td>你在 <strong>窗口 A</strong> 吗？去 <strong>窗口 B</strong>（标题带 Extension Development Host）</td></tr><tr><td>发送后 <code>fetch failed</code></td><td>终端是否 <code>npm run ch28:server</code>；Key 是否 export</td></tr><tr><td>命令面板没有 bagent</td><td>同样要在 <strong>窗口 B</strong> 里按 <code>Cmd+Shift+P</code></td></tr><tr><td>改代码没变化</td><td><code>ch30:compile</code> → 窗口 B <strong>Cmd+R</strong> 或重新 F5</td></tr><tr><td>调试控制台一堆 Claude/punycode 警告</td><td>别的扩展日志，与 bagent 无关</td></tr></tbody></table><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 能说出 Webview 与 extension 主机各干什么吗？</li><li>[ ] 换主题色为何能跟着 VS Code 变？（用了 <code>--vscode-*</code> CSS 变量）</li><li>[ ] server 要改吗？——不用，仍是 ch28。</li></ul><hr><p><a href="/bagent/chapters/29-agent-split.html">← 第 29 课</a> · <a href="/bagent/chapters/31-vscode-spawn.html">第 31 课 · spawn 子进程</a> · <a href="/bagent/chapters/28-agent-network.html">第 28 课</a></p>`,68)])])}const u=e(i,[["render",l]]);export{b as __pageData,u as default};
